from pathlib import Path
p=Path("sentient/src/application/production-mission-control-synthesis.ts")
s=p.read_text()
def one(old,new):
 global s
 n=s.count(old)
 if n!=1: raise SystemExit(f"synthesis expected one anchor, got {n}: {old[:120]!r}")
 s=s.replace(old,new,1)
one('import type { SpawnExecutionBackendV1 } from "../spawn/execution-contracts.js";','import type { SpawnExecutionBackendV1 } from "../spawn/execution-contracts.js";\nimport { objectiveAbortSignalV1, objectiveExecutionEnvelopeV1 } from "./objective-budget.js";')
one('  readonly #synthesis: Phase1CognitionPort | null;\n  readonly #acceptance: Phase1AcceptancePolicyV1 | null;','  readonly #synthesis: Phase1CognitionPort | null;\n  readonly #acceptance: Phase1AcceptancePolicyV1 | null;\n  readonly #state: PostgresSpawnObjectiveRepository;')
one('    super(baseInput);\n    this.#synthesis = input.rootSynthesis ?? null;','    super(baseInput);\n    this.#state = input.state;\n    this.#synthesis = input.rootSynthesis ?? null;')
one('  public override async run(input: SentientObjectiveInput): Promise<unknown> {\n    const started = Date.now();\n    const raw = await super.run(input);','  public override async run(input: SentientObjectiveInput): Promise<unknown> {\n    const objectiveEnvelope = objectiveExecutionEnvelopeV1(input);\n    const objectiveSignal = objectiveAbortSignalV1(objectiveEnvelope);\n    const raw = await super.run(input);')
one('    const synthesisBudgetMs = rootSynthesisBudgetMsV1(\n      started,\n      Date.now(),\n      resultRef,\n    );\n    if (synthesisBudgetMs <= 0) {\n      acceptanceEvent(input.objectiveId, null, null, false, "root_direct_budget_exhausted");\n      return raw;\n    }\n\n    const turn = await bounded(\n      executeSentientPhase1TurnV1(\n        {\n          requestId: `root-synthesis:${input.objectiveId}`,\n          sessionId: input.sessionId,\n          taskId: input.objectiveId,\n          userRequest: prompt,\n        },\n        { cognition: this.#synthesis, acceptancePolicy: this.#acceptance },\n      ),\n      synthesisBudgetMs,\n    );\n    if (turn === null) {\n      acceptanceEvent(input.objectiveId, null, null, false, "synthesis_timeout");\n      return raw;\n    }\n','    const rootExecution = await this.#state.getSpawnExecution(`root:${input.objectiveId}`);\n    const remaining = rootExecution?.remainingBudgets ?? null;\n    const now = Date.now();\n    const remainingRuntimeMs = remaining?.maxRuntimeMs ?? Math.max(0, objectiveEnvelope.absoluteDeadlineMs - now);\n    const absoluteDeadlineMs = Math.min(objectiveEnvelope.absoluteDeadlineMs, now + remainingRuntimeMs);\n    const remainingTotalTokens = remaining?.maxTotalTokens ?? objectiveEnvelope.maxTokens;\n    const tokenCaps = synthesisTokenCapsV1(\n      remainingTotalTokens,\n      remaining?.maxInputTokens ?? null,\n      remaining?.maxOutputTokens ?? null,\n    );\n    const remainingCostMicros = remaining?.maxCostMicros ?? objectiveEnvelope.maxCostMicros;\n    if (\n      objectiveSignal.aborted\n      || absoluteDeadlineMs <= now\n      || tokenCaps.maxInputTokens <= 0\n      || tokenCaps.maxOutputTokens <= 0\n      || (remainingCostMicros !== null && remainingCostMicros <= 0)\n    ) {\n      acceptanceEvent(input.objectiveId, null, null, false, "synthesis_budget_exhausted");\n      return raw;\n    }\n    const runtimeSignal = AbortSignal.timeout(Math.max(1, absoluteDeadlineMs - now));\n    const signal = AbortSignal.any([objectiveSignal, runtimeSignal]);\n    const turn = await executeSentientPhase1TurnV1(\n      {\n        requestId: `root-synthesis:${input.objectiveId}`,\n        sessionId: input.sessionId,\n        taskId: input.objectiveId,\n        userRequest: prompt,\n      },\n      {\n        cognition: this.#synthesis,\n        acceptancePolicy: this.#acceptance,\n        invocationControl: {\n          objectiveId: input.objectiveId,\n          executionId: `root-synthesis:${input.objectiveId}`,\n          parentExecutionId: `root:${input.objectiveId}`,\n          absoluteDeadlineMs,\n          maxInputTokens: tokenCaps.maxInputTokens,\n          maxOutputTokens: tokenCaps.maxOutputTokens,\n          ...(remainingCostMicros === null ? {} : { maxCostMicros: remainingCostMicros }),\n          signal,\n        },\n      },\n    );\n')
one('async function bounded<T>(promise: Promise<T>, ms: number): Promise<T | null> {\n  let timer: ReturnType<typeof setTimeout> | null = null;\n  try {\n    return await Promise.race([\n      promise,\n      new Promise<null>((resolve) => { timer = setTimeout(() => resolve(null), ms); }),\n    ]);\n  } finally {\n    if (timer !== null) clearTimeout(timer);\n  }\n}\n','function synthesisTokenCapsV1(\n  total: number | null,\n  remainingInput: number | null,\n  remainingOutput: number | null,\n): { maxInputTokens: number; maxOutputTokens: number } {\n  const totalCap = total ?? 9_216;\n  if (totalCap <= 1) return { maxInputTokens: 0, maxOutputTokens: 0 };\n  const output = Math.min(1_024, remainingOutput ?? 1_024, Math.max(1, Math.floor(totalCap / 4)));\n  const input = Math.min(8_192, remainingInput ?? 8_192, Math.max(0, totalCap - output));\n  return { maxInputTokens: input, maxOutputTokens: Math.min(output, totalCap - input) };\n}\n')
p.write_text(s)
print("synthesis D4 patch ready")
